from launch_common24 import *
j=base('launch_exchange_ventilation_lab','Exchange and ventilation: two linked jobs','Move air, maintain a gradient and explain diffusion','Explain how ventilation and alveolar structure support gas exchange, using an idealised comparison model.',5,'C33 improved revisit of earlier diffusion/lung lessons, linked to Pearson8.2–8.5B. Fick’s-law reasoning is Biology-specific content, not labelled Higher-only. The core connects ventilation, gradients and short diffusion distance; no human breathing practical is required.',['Diffusion is net movement down a concentration gradient.','Blood circulates between lungs and tissues.','A rate describes change per unit time.'],['Distinguish ventilation from diffusion and cellular respiration.','Explain thin, moist, large-area alveoli and blood flow using a mechanism.','Predict the effect of changing one diffusion factor while holding others constant.'],[('ventilation','Movement of air into and out of the lungs.'),('alveolus','A small air sac in the lungs where gases exchange with capillary blood.'),('concentration gradient','A difference in concentration across a distance.'),('diffusion distance','The distance particles must cross during exchange.'),('diaphragm','A muscular sheet that changes thoracic volume during breathing.'),('relative rate index','A model number for comparing rates; it is not a calibrated measurement of a person.')])
j['sources'] += [source('NHLBI: What breathing does for the body','https://www.nhlbi.nih.gov/health/lungs/breathing-benefits','Checked alveolar exchange and oxygen/carbon-dioxide transport.'),source('NHLBI: How the lungs work','https://www.nhlbi.nih.gov/health/lungs','Checked ventilation context. All diagrams and relative-index examples are original classroom models.')]
j['misconceptions']=[misconception('Breathing, gas exchange and respiration are the same process.','Ventilation moves air; diffusion exchanges gases; cellular respiration releases energy in cells.','Ask where each process occurs and what changes.'),misconception('The lungs pump oxygen directly into every body cell.','Air enters by ventilation; oxygen diffuses into blood, which transports it towards tissues.','Trace the separate air, exchange and blood stages.'),misconception('A thicker barrier helps gases cross faster.','With other factors held constant, a longer diffusion distance reduces rate.','Compare modelP andR.'),misconception('A relative model index is a real clinical gas reading.','It compares a specified model and has no clinical calibration.','Ask what the index leaves out.')]
v1=visual('Oxygen and carbon dioxide diffuse in opposite directions','Simplified alveolar exchange: oxygen diffuses from alveolar air into arriving oxygen-poor capillary blood; carbon dioxide diffuses from blood into alveolar air. A thin barrier separates air and blood. Directions are based on gradients, not active pumping of gases.',[ellipse(45,145,345,270,fill='#EDF4F8',stroke=BLUE),text(80,175,270,95,'Alveolar air\nHigher oxygen than\narriving blood',27,True,'center'),rect(610,140,345,275,fill='#F6E5E5',stroke='#B34D4D'),text(640,170,285,95,'Arriving blood\nLower oxygen than\nalveolar air',27,True,'center'),line(455,125,455,430,color=INK,width=5),line(495,125,495,430,color=INK,width=5),line(340,295,600,295,True,color=BLUE),text(375,243,210,40,'Oxygen',27,True,'center'),line(600,370,340,370,True,color='#B34D4D'),text(355,385,245,45,'Carbon dioxide',26,True,'center'),text(45,465,470,70,'Thin, moist exchange barrier\nShort diffusion distance',26,True),text(585,465,370,70,'Blood flow and ventilation\nhelp maintain gradients',25,True)])
v2=visual('Ventilation changes volume and pressure','Two-panel schematic of quiet breathing. Inhalation: diaphragm contracts/flattens, ribs move up/out, thoracic volume rises and pressure falls below atmospheric pressure so air enters. Quiet exhalation: muscles relax and elastic recoil reduces volume, raising pressure so air leaves.',[text(55,82,390,45,'Inhalation',29,True,'center'),text(555,82,390,45,'Quiet exhalation',29,True,'center'),rect(85,160,330,225,fill='#EEF3F7',stroke=BLUE),ellipse(135,195,95,150),ellipse(270,195,95,150),line(250,130,250,215,True,color=BLUE,width=6),line(110,390,390,390,color=PURPLE,width=7),rect(585,195,330,190,fill='#EEF3F7',stroke=BLUE),ellipse(635,220,95,115),ellipse(770,220,95,115),line(750,215,750,130,True,color=BLUE,width=6),line(610,390,750,345,color=PURPLE,width=7),line(750,345,890,390,color=PURPLE,width=7),text(55,420,390,110,'Diaphragm contracts/flattens\nVolume rises; pressure falls\nAir enters',25,True,'center'),text(555,420,390,110,'Diaphragm relaxes; recoil\nVolume falls; pressure rises\nAir leaves',25,True,'center')])
v3=bars('Constructed model: compare one factor','Idealised relative diffusion-rate indices calculated as area×concentration difference÷thickness with the same omitted proportionality constant. P:2×4/1=8;Q:4×4/1=16;R:2×4/2=4. This is a mathematical comparison, not measured physiological data.',['P','Q','R'],[8,16,4],20,'Relative model rate index; not a clinical unit')
rows=[['P','2','4','1'],['Q','4','4','1'],['R','2','4','2']]
j['slides']=[slide('Opening',2,'The air moved. Has exchange happened yet?',['Mission: separate air movement from particle movement.','Then connect both to blood transport.'],'Invite pupils to distinguish opening a door from people moving through it as a limited analogy; return immediately to actual gas mechanisms.'),slide('Retrieval',3,'What drives diffusion?',['R1. In which direction is net diffusion?','R2. What does circulating blood transport from the lungs?','R3. Is respiration simply another word for breathing?'],'R1down a concentration gradient. R2oxygen, with other transported substances. R3no:cellular respiration releases energy in cells.'),slide('I do',4,'Follow one gas at a time',['Oxygen diffuses from alveolar air into blood.','Carbon dioxide diffuses from blood into alveolar air.','Each gas follows its own gradient.'],'Think aloud along oxygen arrow, then carbon-dioxide arrow. State that gases cross the thin exchange surface by diffusion; blood and ventilation maintain differences. Do not claim all blood always has one uniform gas concentration.',visual=v1),slide('I do',3,'Air moves because pressure changes',['Inhalation increases thoracic volume and lowers pressure.','Quiet exhalation reverses the volume change.'],'Model diaphragm contraction/flattening plus ribs up/out. Pressure falls below surrounding air pressure, so air enters. Quiet exhalation follows relaxation and elastic recoil; forced exhalation is beyond this core model.',visual=v2),slide('I do',3,'Explain the exchange adaptations',['Large area offers more exchange surface.','A thin barrier gives a short diffusion distance.','Ventilation and flow help sustain gradients.'],'Use the constructed model to illustrate one factor at a time. P→Q doubles area with other model factors equal; P→R doubles thickness. A relative index is not an oxygen saturation, clinical reading or empirical result.',visual=v3),slide('We do',3,'Diffusion design desk',['W1. Which pair changes area only? Predict the faster case.','W2. Which pair changes thickness only? Predict the slower case.'],'P/Q area-only:Qfaster in the model. P/R thickness-only:Rslower. Ask pupils to identify the unchanged columns before giving a conclusion.',table=table(['Case','Relative area','Relative gradient','Relative thickness'],rows,'Constructed idealised comparison; rate index=area×gradient/thickness.')),slide('We do',2,'Trace a ventilation failure in the model',['W3. Fresh air stops being replaced while exchange continues.','Why may the oxygen gradient decrease?'],'Alveolar oxygen is removed into blood and not replenished as effectively; the difference can shrink, reducing net oxygen diffusion if other factors are comparable. This is a conceptual case; pupils do not hold their breath.',visual=v1),slide('We do',2,'Repair a three-process caption',['“The diaphragm respires oxygen into the blood.”','Replace it with ventilation, diffusion and respiration in the right places.'],'Diaphragm action supports ventilation; oxygen diffuses across alveoli into blood; cells use oxygen in aerobic respiration. No process has to be personified.',reveal='Ventilation moves air. Diffusion exchanges gases. Cellular respiration releases energy in cells.'),slide('Hinge',3,'Which explanation names the mechanism?',['Choose the supported claim.'],'First option correct. Use the two-panel diagrams to separate air movement from gas diffusion.',options=[option('A thin exchange barrier helps because it shortens diffusion distance.',True,'Yes, with other factors equal, a shorter path supports faster diffusion.'),option('The diaphragm directly pushes oxygen through blood-cell membranes.',False,'It changes thoracic volume/pressure; gas exchange across the lung barrier is diffusion.'),option('A large surface always guarantees fast exchange, regardless of every other factor.',False,'Gradient and distance also matter; one favourable factor is not a universal guarantee.')]),slide('You do',1,'Build an exchange explanation',['Choose your route.','Use labelled arrows, the comparison table and a model limit.'],'Core focuses on mechanisms and fair factor comparisons. The formula extension is Biology-specific reasoning, not inherently Higher-only.'),slide('You do',10,'Make the link from structure to function',['Structure → effect on exchange → reason.','Separate model predictions from measurements.'],'SupportedS1–S4;standardM1–M4;stretchT1–T4. Check the pressure direction before asking for extended prose.'),slide('Review',2,'Audience asks: what actually moves?',['L1. Share one explanation.','Audience asks whether it concerns air, gas particles or blood.'],'Pupil improves a process label or identifies a relevant gradient. Quiet teacher/TA audience is valid.'),slide('Review',1,'Use three precise verbs',['Ventilate air. Diffuse gases. Transport blood.','Then explain cellular respiration separately.'],'Accept accurate wording rather than these exact verbs. Ask pupil to correct one misleading “pumps oxygen into cells” claim.'),slide('Exit',1,'Three mechanism checks',['E1. What happens to pressure during inhalation?','E2. Why does a thin barrier help diffusion?','E3. Name one process distinct from respiration.'],'E1falls below atmospheric pressure as volume rises. E2shorter path. E3ventilation/diffusion. No breathing exercise is requested.'),slide('Exit',0,'Next useful step',['Pressure • gas gradient • diffusion distance • model scope.'],'Shared exit minute; use an annotated diagram if writing demand is a barrier.')]
j['pupilPages']=[page('Shared evidence | Idealised exchange comparison','All values are relative model inputs, not measured human data. Hold the omitted proportionality constant the same.',[tb(['Case','Relative area','Relative concentration difference','Relative thickness'],rows),txt('Model rule: relative rate index=area×concentration difference÷thickness. It compares directions and ratios; it has no calibrated physiological unit.'),dict(type='cards',cards=[dict(title='Air movement case',text='During quiet inhalation, diaphragm contraction and rib movement increase thoracic volume. Compare pressure inside with surrounding air.'),dict(title='Gradient case',text='Oxygen is moving from alveolar air into arriving blood. In this scenario, fresh air replacement is reduced while exchange continues.')]),response('W1. Area-only pair and prediction. W2. Thickness-only pair and prediction. W3. Explain the fresh-air effect.',4)]),page('Supported route | Connect the three jobs','Word bank: ventilation; diffusion; blood transport; respiration; gradient; distance.',[response('S1. Draw oxygen and carbon-dioxide arrows across an alveolar surface. Label air and blood.',4),response('S2. Explain how diaphragm contraction can make air enter during inhalation.',3),response('S3. CompareP/Q andP/R. Name the changed factor and predict the faster/slower model case.',4),response('S4. Explain one alveolar adaptation and distinguish ventilation from cellular respiration.',4)]),page('Standard route | Structure explains exchange','Use causal links rather than listing features alone.',[response('M1. Explain the roles of ventilation and blood flow in maintaining gas gradients.',4),response('M2. Explain how large area and a thin, moist barrier support gas exchange.',4),response('M3. Describe quiet inhalation and exhalation using muscles, volume, pressure and air direction.',4),response('M4. Use the table to justify two one-factor comparisons and state why its indices are not clinical readings.',3)]),page('Stretch route | Quantify a model carefully','Optional Biology-specific calculation; Fick-style reasoning is not labelled Higher-only. Use the supplied model rule.',[response('T1. Calculate relative indices forP,Q andR. CompareQ withP andR withP using ratios.',4),response('T2. A new case doubles area and doubles thickness, with the same gradient. Predict its rate index relative to the original and explain.',3),response('T3. A cube ofside1unit has area6 and volume1; a cube ofside2units has area24 and volume8. Calculate both surface-area:volume ratios and explain one implication for exchange.',4),response('T4. State two limitations of using this idealised model to explain a real lung.',3)]),page('Exit and reflection | Say how and why','Use scientific process words precisely.',[response('E1. What happens to thoracic pressure during inhalation, and why does air enter?',3),response('E2. Why can a thin exchange barrier increase diffusion rate?',2),response('E3. Distinguish ventilation or gas diffusion from cellular respiration.',3),response('L1. What did your audience ask? Record one stronger mechanism explanation.',3),choices('Next useful step',['Explain volume and pressure.','Trace separate gas gradients.','Link structure with exchange.','Limit a model-based claim.'])])]
j['answers']=[qa('Retrieval and We do','R1down a concentration gradient;R2oxygen;R3respiration differs from breathing. W1P/Q changes area only;Qhas twice the index. W2P/R changes thickness only;Rhas half the index. W3less fresh-air replacement can reduce alveolar oxygen and the oxygen gradient as exchange continues.'),qa('Caption repair and hinge','Ventilation moves air because volume/pressure changes. Oxygen diffuses into blood across alveoli. Cellular respiration releases energy in cells. Correct hinge:thin barrier shortens diffusion distance; diaphragm does not directly force oxygen across membranes.'),qa('S1 / M1','Oxygen arrow air→blood;carbon dioxide arrow blood→air under the stated gradients. Ventilation replenishes air and removes carbon dioxide; blood flow brings relatively oxygen-poor blood and carries exchanged gases away, helping maintain differences.'),qa('S2 / M3','During inhalation diaphragm contracts/flattens and external intercostals raise ribs up/out; thoracic volume rises, pressure falls below atmospheric and air enters. Quiet exhalation involves relaxation and elastic recoil, reducing volume and raising pressure so air leaves.'),qa('S3 / M4','P/Q differs only in area:Qfaster. P/R differs only in thickness:Rslower. Inputs are relative and idealised, so no clinical concentration, saturation or measured exchange rate can be read from the index.'),qa('S4 / M2','Large total area supports more simultaneous exchange; a thin alveolar/capillary barrier shortens the diffusion path; moisture enables gases to dissolve. Gradients and blood/air replacement are also important. Cellular respiration is an energy-releasing process in cells, not air movement.'),qa('T1','P=2×4/1=8;Q=4×4/1=16;R=2×4/2=4. Q/P=2;R/P=0.5. These are relative indices, with the same proportionality constant.'),qa('T2','Unchanged:twice the area divided by twice the thickness gives the original index if gradient and other model assumptions match.'),qa('T3','Small cube6:1;larger cube24:8=3:1. The larger cube has less surface per unit volume; increasing size can make diffusion-only exchange less adequate for its volume, depending on shape and demand.'),qa('T4','Idealised uniform barrier/gradient, no real units or diffusion coefficient, no changing blood flow/ventilation, no heterogeneous alveoli or individual physiology. Any two specific limits are valid.'),qa('Exit and assessment','E1pressure falls as volume increases, so air moves in from higher external pressure. E2shorter diffusion distance. E3accurate ventilation/diffusion versus respiration distinction. Secure core requires a mechanism, not a feature list; reteach with one gas arrow and one pressure arrow.')]
j['teacherNotes'] += ['No pupil breath holding, forced breathing, lung-capacity testing or exercise is needed. The entire lesson uses models and supplied evidence.','Fick’s-law factors and the optional relative-index calculation are Biology-specific in this specification; do not label them automatically Higher-tier.','Interactive and paperW1–W3 use identical model inputs. The animated arrows represent direction, not actual particle counts or an individual’s gas exchange.']
j['interactive']=interactive('Exchange lab: compare one factor','Idealised relative model, not a human experiment.',[step('Which pair tests area alone?','P andQ.','P andR.',v3,'P/Q shares gradient and thickness; only area differs.','P/R changes thickness, not area.'),step('Why canRhave a lower rate index thanP?','Its barrier is thicker.','Its area is larger.',v3,'Rhas twice the thickness with other model factors the same.','Area is the same forP andR.'),step('What makes air enter during inhalation?','Thoracic pressure falls below surrounding air pressure.','The diaphragm pulls individual oxygen molecules into blood.',v2,'Increasing thoracic volume lowers pressure, producing airflow into lungs.','Gas exchange into blood is diffusion across the alveolar barrier.')])
save(j)
